-- CONSULTAS DE EJEMPLO
-- 1. Ver todos los registros
SELECT * FROM `encuestas_pai`;

-- 2. Buscar por número de encuesta
SELECT * FROM `encuestas_pai` WHERE `No` = 1;

-- 3. Buscar por encuestador
SELECT * FROM `encuestas_pai` WHERE `ENCUESTADOR` = 'Maykely Cruz';

-- 4. Buscar personas mayores de una edad
SELECT `No`, `EDAD`, `SEXO`, `Barrio_cadena` FROM `encuestas_pai` WHERE `EDAD` >= 60;

-- 5. Buscar viviendas a determinada distancia del río
SELECT * FROM `encuestas_pai` WHERE `DISTANCIA_DEL_RIO` <= 20;

-- 6. Buscar por barrio
SELECT * FROM `encuestas_pai` WHERE `Barrio_cadena` = 'Santa Ana';

-- 7. Consultar solo los datos relacionados con inundaciones
SELECT `No`, `Ha_sido_afectado_por_inundaciones`, `Sabe_que_hacer_en_caso_de_inundacion`, `Nospodrianarrarsuexperienciaanteunainundacionvivida` FROM `encuestas_pai`;

-- 8. Buscar texto dentro de observaciones
SELECT * FROM `encuestas_pai` WHERE `OBSERVACIONES` LIKE '%inunda%';

-- 9. Contar registros por barrio
SELECT `Barrio_cadena`, COUNT(*) AS `cantidad` FROM `encuestas_pai` GROUP BY `Barrio_cadena` ORDER BY `cantidad` DESC;

-- 10. Consultar cualquier columna: reemplaza NOMBRE_COLUMNA y VALOR
-- SELECT * FROM `encuestas_pai` WHERE `NOMBRE_COLUMNA` = 'VALOR';